-- ========================================================================
-- APPLICATION: EMPLOYEE EDUCATION MANAGEMENT SYSTEM
-- TARGET DATABASE: ORACLE 11g R2 / 12c+
-- SCRIPT: 02_Seed_MasterData.sql
-- DESCRIPTION: Populates Master Qualifications, Sub-Qualifications,
--              Universities, Subjects, Admin Users and Migration Mappings.
--              Includes all items from education values _ filtered.txt
--              with duplicates eliminated and canonical catalogs preserved.
-- ========================================================================
SET DEFINE OFF;

-- 1. DEFAULT ADMIN USERS
MERGE INTO EDU_ADMIN_USERS dest
USING (SELECT '1001' AS PCNO, 'System Administrator' AS USER_NAME, 'Admin' AS ROLE FROM DUAL) src
ON (dest.PCNO = src.PCNO)
WHEN NOT MATCHED THEN INSERT (PCNO, USER_NAME, ROLE, IS_ACTIVE) VALUES (src.PCNO, src.USER_NAME, src.ROLE, 1);

